#!/usr/bin/env python3
"""Safely update an existing HistoryIT project with the reviewed MVP source tree.
Generated from the completed project snapshot. Run from the project root or its parent.
"""
from pathlib import Path
import base64, gzip, io, os, shutil, tarfile, tempfile, time

PAYLOAD = ''
PRESERVE = {'.env', 'credentials', 'governing'}

def find_target(cwd: Path) -> Path:
    candidates = [cwd, cwd/'history-it-project', cwd/'HitoryIT'/'history-it-project', cwd/'historyit-archive-mvp']
    for p in candidates:
        if (p/'app').is_dir() and ((p/'requirements.txt').exists() or (p/'pyproject.toml').exists()):
            return p
    raise SystemExit('Could not find the HistoryIT project. Run this script from the project root or its parent.')

def main() -> None:
    cwd = Path.cwd().resolve()
    target = find_target(cwd)
    stamp = time.strftime('%Y%m%d_%H%M%S')
    backup = target.parent / (target.name + '.historyit_update_backup_' + stamp)
    backup.mkdir(parents=True, exist_ok=False)
    with tempfile.TemporaryDirectory(prefix='historyit_update_') as tmp:
        unpack = Path(tmp)
        raw = gzip.decompress(base64.b64decode(PAYLOAD))
        with tarfile.open(fileobj=io.BytesIO(raw), mode='r:') as tar:
            try:
                tar.extractall(unpack, filter='data')
            except TypeError:
                tar.extractall(unpack)
        files = [p for p in unpack.rglob('*') if p.is_file()]
        for src in files:
            rel = src.relative_to(unpack)
            dst = target / rel
            if rel.name == '.env' or rel.parts and rel.parts[0] in {'credentials'}:
                continue
            if rel.parts and rel.parts[0] == 'governing' and dst.exists():
                continue
            if dst.exists():
                copy = backup / rel
                copy.parent.mkdir(parents=True, exist_ok=True)
                if dst.is_file(): shutil.copy2(dst, copy)
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    print(f'Updated: {target}')
    print(f'Backup:  {backup}')
    print('Preserved: .env, credentials/, governing/')
    print('Next: create/activate a virtualenv, install requirements, then run the tests listed in README.md.')

if __name__ == '__main__':
    main()
